sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // check the email automation flag for the client 
    current.does_client_prefer_proactive_contact = current.contact.u_email_automation;
    //CHECKING FOR CLIENT CONTACT INFORMATION IN THE contact table/TRADECASE
    var clientContactRecord = new GlideRecord('customer_contact');
    clientContactRecord.addQuery("u_counterparty_code", current.client);
    clientContactRecord.query();

	//Scenario 1 - Contact Exist
    if (clientContactRecord.next()) {
			//checking client contact exist, active is false
            if (clientContactRecord.active == false && clientContactRecord.u_contact_type != "Escalation Contact") {
                var shortDescriptionInactive = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.short.description.contact.missing.inactive");
				var descInactive = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.description.missing.inactive");
                createExceptionWorkItem(shortDescriptionInactive, descInactive);
            }
    }
    //Scenario 2 - Contact don't exsit/missing
    else {
        var shortDescriptionMissing = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.short.description.contact.missing.inactive");
		var descMissing = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.description.missing.inactive");
        createExceptionWorkItem(shortDescriptionMissing, descMissing);
    }
    //creating new task
    function createExceptionWorkItem(shortDesc, desc) {
        var getAssignmentGrp = new GlideRecord('sys_user_group');
        var MocsGroup = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs");
        getAssignmentGrp.get('sys_id', MocsGroup);

        var createExceptionTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        createExceptionTask.initialize();
        createExceptionTask.short_description = shortDesc;
        createExceptionTask.description = desc;
        createExceptionTask.assignment_group = getAssignmentGrp.sys_id;
        createExceptionTask.setValue('parent', current.sys_id);
		createExceptionTask.entity = current.entity;

		// Check if a task already exists if not then only create a new task
        if (checkTaskAlreadyExists(current.sys_id, shortDesc) == false)
            createExceptionTask.insert();
    }
    function checkTaskAlreadyExists(tradeCaseRef, shortDesc) {
        // Function takes trade case reference and short description as parameters and returns true/false if a task already exists on the same trade case
        var checkTaskExists = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        checkTaskExists.addEncodedQuery('parent=' + tradeCaseRef + '^short_description=' + shortDesc);
        checkTaskExists.query();
        if (checkTaskExists.next())
            return true;
        else
            return false;
    }
})(current, previous);
